describe('Faceted Search Without Page Reload', () => {
  beforeEach(() => {
    cy.visit('/search');
    cy.get('[data-testid="search-input"]').type('laptop');
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="search-results"]').should('be.visible');
  });

  it('should update search results when clicking a facet filter without page reload', () => {
    const initialUrl = cy.url();

    cy.get('[data-testid="facet-brand"]').should('be.visible');
    cy.get('[data-testid="facet-option-dell"]').click();

    cy.url().should('not.equal', initialUrl);
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').each(($item) => {
      cy.wrap($item).should('contain', 'Dell');
    });

    cy.window().then((win) => {
      expect(win.performance.navigation.type).not.to.equal(1);
    });
  });

  it('should handle multiple facet selections and update results dynamically', () => {
    cy.get('[data-testid="facet-price"]').should('be.visible');
    cy.get('[data-testid="facet-option-price-500-1000"]').click();

    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-count"]').then(($count) => {
      const initialCount = parseInt($count.text());
      expect(initialCount).to.be.greaterThan(0);
    });

    cy.get('[data-testid="facet-brand"]').should('be.visible');
    cy.get('[data-testid="facet-option-hp"]').click();

    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="active-filter-price-500-1000"]').should('be.visible');
    cy.get('[data-testid="active-filter-hp"]').should('be.visible');
  });

  it('should remove facet filter and update results when clicking remove button', () => {
    cy.get('[data-testid="facet-option-dell"]').click();
    cy.get('[data-testid="active-filter-dell"]').should('be.visible');

    cy.get('[data-testid="result-item"]').then(($items) => {
      const filteredCount = $items.length;
      expect(filteredCount).to.be.greaterThan(0);
    });

    cy.get('[data-testid="remove-filter-dell"]').click();
    cy.get('[data-testid="active-filter-dell"]').should('not.exist');
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);
  });

  it('should display loading state while updating results with facet selection', () => {
    cy.get('[data-testid="facet-option-dell"]').click();
    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
    cy.get('[data-testid="search-results"]').should('be.visible');
  });

  it('should handle edge case of selecting facet with no matching results', () => {
    cy.get('[data-testid="facet-option-dell"]').click();
    cy.get('[data-testid="facet-price"]').should('be.visible');
    cy.get('[data-testid="facet-option-price-5000-plus"]').click();

    cy.get('[data-testid="no-results-message"]').should('be.visible');
    cy.get('[data-testid="no-results-message"]').should('contain', 'No results found');
    cy.get('[data-testid="search-results"]').should('be.empty');
  });
});
